def write(kind: str, request: dict, content: str) -> None:
    path = fixture_path(FIXTURES, kind, request)
    path.write_text(json.dumps({"request": request, "content": content, "seeded": True}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


class SeedNemotronClient(NemotronClient):
    def __init__(self, scenario_id: str) -> None:
        super().__init__(FIXTURES)
        self.scenario_id = scenario_id
        self.caller_index = 0

    def advise(self, verdict: Verdict, transcript: list[Turn]) -> dict[str, str]:
        if self.scenario_id in MESSAGE_ADVICE:
            answer = MESSAGE_ADVICE[self.scenario_id]
        else:
            answer = ADVICE[self.scenario_id][self.caller_index]
            self.caller_index += 1
        write("advise", self.advise_request(verdict, transcript), canonical_json(answer))
        return answer


def main() -> None:
    FIXTURES.mkdir(exist_ok=True)
    live = [path.name for path in FIXTURES.glob("*.json") if json.loads(path.read_text(encoding="utf-8")).get("seeded") is False]
    if live and "--force" not in sys.argv:
        raise SystemExit(f"{len(live)} fixtures were recorded live; seeding would delete them. Pass --force to do it anyway.")
    for path in FIXTURES.glob("*.json"):
        path.unlink()
    for scenario_path in sorted((ROOT / "scenarios").glob("*.json")):
        scenario = json.loads(scenario_path.read_text(encoding="utf-8"))
        transcript: list[Turn] = []
        caller_index = 0
        for raw_turn in scenario["turns"]:
            transcript.append(Turn(**raw_turn))
            if raw_turn["speaker"] == "caller":
                write("extract", NemotronClient.extract_request(transcript), canonical_json({"signals": OUTPUTS[scenario["id"]][caller_index]}))
                caller_index += 1
    examples = json.loads((ROOT / "messages" / "examples.json").read_text(encoding="utf-8"))
    for example in examples:
        transcript = [Turn(speaker="caller", text=example["text"], t=0)]
        write("extract", NemotronClient.extract_request(transcript), canonical_json({"signals": MESSAGE_OUTPUTS[example["id"]]}))
    for tactic, query in TACTIC_QUERIES.items():
        request = TavilyClient.request(query, OFFICIAL_DOMAINS)
        content = {"results": [{"url": url, "title": title, "content": snippet} for url, title, snippet in SOURCES[tactic]]}
        write("search", request, canonical_json(content))
    for scenario_path in sorted((ROOT / "scenarios").glob("*.json")):
        scenario = json.loads(scenario_path.read_text(encoding="utf-8"))
        session = CallSession(llm=SeedNemotronClient(scenario["id"]), search=TavilyClient(FIXTURES))
        for raw_turn in scenario["turns"]:
            session.on_turn(Turn(**raw_turn))
    for example in examples:
        session = CallSession(llm=SeedNemotronClient(example["id"]), search=TavilyClient(FIXTURES))
        session.on_turn(Turn(speaker="caller", text=example["text"], t=0))


if __name__ == "__main__":
    main()
